  Future<void> _pickFile()async{final r=await FilePicker.platform.pickFiles(type:FileType.custom,allowedExtensions:['pdf','jpg','png','docx'],withData:true);if(r?.files.first.bytes!=null)setState((){_selectedFileBytes=r!.files.first.bytes;_selectedFileName=r.files.first.name;});}
  Future<void> _submit()async{if(_package==null||_slot==null||!(_formKey.currentState?.validate()??false))return;final booking=await ref.read(bookingsControllerProvider.notifier).requestBooking(lawyerId:widget.lawyer.profileId,scheduledAt:_slot!,packageName:_package!.title,consultationType:_consultationType,description:_descriptionController.text.trim(),documentBytes:_selectedFileBytes,documentName:_selectedFileName);if(!mounted)return;if(booking==null){final error=ref.read(bookingsControllerProvider).error;ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(error?.toString()??'تعذر إنشاء الحجز'),backgroundColor:AppColors.error));return;}await showDialog<void>(context:context,barrierDismissible:false,builder:(d)=>AlertDialog(title:const Text('تم إنشاء الحجز'),content:const Text('الحجز الآن في حالة «قيد انتظار الدفع». أرسل الدفع من تفاصيل الحجز، ثم يبقى «قيد معالجة الدفع» حتى تعتمد الإدارة العملية.'),actions:[TextButton(onPressed:()=>Navigator.pop(d),child:const Text('حسنًا'))]));if(mounted)Navigator.pop(context);}
